/* ================= Onglets Textes ================= */
function renderTextTabs(){
  const box = $('textTabs'); box.innerHTML = '';
  state.texts.forEach((t,i)=>{
    const b = document.createElement('button');
    b.className = 'tab' + (i===state.activeTextIndex?' active':'');
    b.innerHTML = `Texte ${i+1}` + (state.texts.length>1 ? ` <span class="tabx" data-i="${i}">✕</span>` : '');
    b.addEventListener('click', (e)=>{
      if(e.target.classList.contains('tabx')){
        e.stopPropagation();
        state.texts.splice(i,1);
        if(state.activeTextIndex>=state.texts.length) state.activeTextIndex = state.texts.length-1;
        renderTextTabs(); loadTextLayerToUI(); render();
        return;
      }
      state.activeTextIndex = i; renderTextTabs(); loadTextLayerToUI(); render();
    });
    box.appendChild(b);
  });
  const add = document.createElement('button');
  add.className = 'tab addtab'; add.textContent = '+ Ajouter un texte';
  add.addEventListener('click', ()=>{
    state.texts.push(defaultTextLayer("NOUVEAU TEXTE"));
    state.activeTextIndex = state.texts.length-1;
    renderTextTabs(); loadTextLayerToUI(); render();
  });
  box.appendChild(add);
}
async function loadTextLayerToUI(){
  const t = activeText();
  $('textContent').value = t.text;
  $('textColor').value = t.color;
  $('textColor2a').value = t.color2a; $('textColor2b').value = t.color2b;
  $('textGradAngle').value = t.gradAngle;
  $('textSize').value = t.size;
  $('textOpacity').value = t.opacity;
  fontSelect.value = t.font;
  $('textX').value = t.x; $('textY').value = t.y;
  document.querySelectorAll('#styleGroup button').forEach(b=>b.classList.toggle('active', b.dataset.v===t.style));
  document.querySelectorAll('#orientGroup button').forEach(b=>b.classList.toggle('active', b.dataset.v===t.orientation));
  $('textCurveRow').style.display = t.orientation==='curve' ? 'block':'none';
  $('textCircleRow').style.display = t.orientation==='circle' ? 'block':'none';
  $('textLineHeightRow').style.display = t.orientation==='horizontal' ? 'block':'none';
  $('textCurve').value = t.curve ?? 0;
  $('textLetterSpacing').value = t.letterSpacing ?? 0;
  $('textLineHeight').value = t.lineHeight ?? 130;
  $('textCircleRadius').value = t.circleRadius ?? 25;
  document.querySelectorAll('#textCircleDir button').forEach(b=>b.classList.toggle('active', +b.dataset.v===(t.circleDir ?? 1)));
  document.querySelectorAll('#textColorMode button').forEach(b=>b.classList.toggle('active', b.dataset.v===t.colorMode));
  $('textColorRow').style.display = t.colorMode==='solid' ? 'flex':'none';
  $('textGradientRow').style.display = t.colorMode==='gradient' ? 'flex':'none';
  $('textShadowOn').checked = !!t.shadowOn;
  $('textShadowRow').style.display = t.shadowOn ? 'block':'none';
  $('textShadowColor').value = t.shadowColor; $('textShadowBlur').value = t.shadowBlur;
  $('textShadowDx').value = t.shadowDx; $('textShadowDy').value = t.shadowDy;
  $('textOutlineOn').checked = !!t.outlineOn;
  $('textOutlineRow').style.display = t.outlineOn ? 'block':'none';
  $('textOutlineColor').value = t.outlineColor; $('textOutlineWidth').value = t.outlineWidth;
  await ensureFontLoaded(t.font);
}

