$('retRemoveBg').addEventListener('change', e=>{
  currentRetouche().removeBg = e.target.checked;
  const active = state.images[state.activeIndex];
  if(active && e.target.checked) active.bgRemovedCanvas = null; // on force un recalcul frais
  render();
});
$('applyRangeBtn').addEventListener('click', ()=>{
  const active = state.images[state.activeIndex];
  if(!active){ toast('Sélectionnez d\'abord une image à utiliser comme modèle.'); return; }
  const from = Math.max(1, +$('rangeFrom').value || 1);
  const to = Math.min(state.images.length, +$('rangeTo').value || 1);
  if(from > to){ toast('La plage n\'est pas valide (le numéro de début doit être inférieur ou égal à la fin).'); return; }
  let count = 0;
  for(let i=from-1; i<to; i++){
    if(i === state.activeIndex) continue;
    state.images[i].retouche = JSON.parse(JSON.stringify(active.retouche));
    state.images[i].zone = JSON.parse(JSON.stringify(active.zone));
    state.images[i].bgRemovedCanvas = null;
    state.images[i].sharpenedCanvas = null;
    state.images[i].sharpenedKey = null;
    count++;
  }
  toast(`Retouche appliquée à ${count} image(s) (de la n°${from} à la n°${to}).`);
  render();
});
$('retReset').addEventListener('click', ()=>{
  const active = state.images[state.activeIndex];
  if(active) active.retouche = defaultRetouche(); else state.retouche = defaultRetouche();
  loadRetoucheToUI();
  render();
});
